nt;\r\n}\r\n\r\n.editor-container ::v-deep .cm-textfield {\r\n  border: 1px solid #dcdfe6;\r\n  border-radius: 4px;\r\n  padding: 4px 8px;\r\n  outline: none;\r\n  font-size: 13px;\r\n  transition: border-color 0.2s;\r\n}\r\n\r\n.editor-container ::v-deep .cm-textfield:focus {\r\n  border-color: #409eff;\r\n}\r\n\r\n.editor-container ::v-deep .cm-button {\r\n  border: 1px solid #dcdfe6;\r\n  background-color: #fff;\r\n  border-radius: 4px;\r\n  padding: 4px 10px;\r\n  font-size: 12px;\r\n  cursor: pointer;\r\n  color: #606266;\r\n  text-transform: none;\r\n  background-image: none;\r\n}\r\n\r\n.editor-container ::v-deep .cm-button:hover {\r\n  color: #409eff;\r\n  border-color: #c6e2ff;\r\n  background-color: #ecf5ff;\r\n}\r\n\r\n.editor-container ::v-deep .cm-button.cm-close-button {\r\n  border: none;\r\n  background: transparent;\r\n  padding: 0 4px;\r\n  font-size: 16px;\r\n  color: #909399;\r\n}\r\n\r\n.editor-container ::v-deep .cm-button.cm-close-button:hover {\r\n  color: #f56c6c;\r\n  background: transparent;\r\n}\r\n\r\n.editor-container ::v-deep .cm-panel.cm-search label {\r\n  font-size: 12px;\r\n  color: #606266;\r\n  gap: 4px;\r\n}\r\n\r\n.editor-container ::v-deep .cm-panel.cm-search [name='close'] {\r\n  display: none;\r\n}\r\n\r\n/* 选中匹配项高亮颜色 */\r\n.editor-container ::v-deep .cm-selectionMatch {\r\n  background-color: #ffff0066;\r\n}\r\n\r\n.editor-container ::v-deep .cm-searchMatch {\r\n  background-color: #ffff0066;\r\n}\r\n\r\n.editor-container ::v-deep .cm-searchMatch-selected {\r\n  background-color: #ff990066;\r\n}\r\n"],"sourceRoot":""}]);
