/**
 * 获取基础 URL
 */
export const getBaseURL = () => {
  return `${location.protocol}//${location.hostname}:${customProcess.devServerPort}`
}

/**
 * 通用 Fetch 封装
 * @param {string} url - 请求地址
 * @param {object} options - 请求配置
 * @returns {Promise}
 */
export const request = (url, options = {}) => {
  const defaultOptions = {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      ...options.headers
    }
  }

  const config = { ...defaultOptions, ...options }

  return fetch(url, config)
    .then((response) => response.json())
    .catch((error) => {
      console.error('Request Error:', error)
      throw error
    })
}

/**
 * 上传文件
 */
export const uploadFile = (endpoint, formData) => {
  const url = `${getBaseURL()}${endpoint}`
  return fetch(url, {
    method: 'POST',
    body: formData
    // 注意: 不要设置 Content-Type，让浏览器自动设置 multipart/form-data 的 boundary
  }).then((res) => res.json())
}

/**
 * GET 请求
 */
export const getFetch = (endpoint, params = {}) => {
  const url = new URL(`${getBaseURL()}${endpoint}`)
  Object.keys(params).forEach((key) => {
    url.searchParams.append(key, params[key])
  })

  return request(url.toString(), { method: 'GET' })
}

/**
 * POST 请求
 */
export const postFetch = (endpoint, data = {}) => {
  const url = `${getBaseURL()}${endpoint}`
  return request(url, {
    method: 'POST',
    body: JSON.stringify(data)
  })
}

/**
 * PUT 请求
 */
export const putFetch = (endpoint, data = {}) => {
  const url = `${getBaseURL()}${endpoint}`
  return request(url, {
    method: 'PUT',
    body: JSON.stringify(data)
  })
}

/**
 * DELETE 请求
 */
export const delFetch = (endpoint) => {
  const url = `${getBaseURL()}${endpoint}`
  return request(url, { method: 'DELETE' })
}
