f;\r\n    border-bottom: 1px solid #e4e7ed;\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n\r\n    h3 {\r\n      margin: 0;\r\n      font-size: 16px;\r\n      font-weight: 500;\r\n      color: #303133;\r\n    }\r\n\r\n    .toolbar {\r\n      display: flex;\r\n      gap: 8px;\r\n    }\r\n  }\r\n\r\n  .lineage-wrapper {\r\n    flex: 1;\r\n    position: relative;\r\n    overflow: auto;\r\n    background: #fff;\r\n  }\r\n\r\n  .lineage-svg {\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    pointer-events: none;\r\n    z-index: 1;\r\n  }\r\n\r\n  .lineage-nodes {\r\n    position: relative;\r\n    width: 100%;\r\n    min-height: 100%;\r\n    z-index: 2;\r\n  }\r\n\r\n  .lineage-node {\r\n    position: absolute;\r\n    width: 220px;\r\n    padding: 12px;\r\n    border-radius: 4px;\r\n    border: 2px solid #e1e1e1;\r\n    background: #f5f7fa;\r\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);\r\n    cursor: move;\r\n    user-select: none;\r\n    transition: background 0.3s;\r\n\r\n    &.checked {\r\n      background: #e1e1e1;\r\n\r\n      .node-label {\r\n        color: #fff;\r\n      }\r\n    }\r\n    &.is-current {\r\n      border: 4px solid rgba(173, 216, 230, 0.8) !important; /* 淡蓝色边框 */\r\n      box-shadow: 0 0 15px rgba(173, 216, 230, 0.5) !important; /* 淡蓝色阴影 */\r\n    }\r\n\r\n    .node-header {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 8px;\r\n      margin-bottom: 10px;\r\n      .node-icon {\r\n        width: 12px;\r\n        height: 12px;\r\n        border-radius: 50%;\r\n        margin-right: 8px;\r\n        flex-shrink: 0;\r\n      }\r\n      .node-checkbox {\r\n        width: 16px;\r\n        height: 16px;\r\n        cursor: pointer;\r\n        flex-shrink: 0;\r\n      }\r\n\r\n      .node-label {\r\n        flex: 1;\r\n        font-size: 14px;\r\n        font-weight: 500;\r\n        color: #606266;\r\n        word-break: break-all;\r\n      }\r\n    }\r\n\r\n    .node-actions {\r\n      display: flex;\r\n      gap: 6px;\r\n\r\n      .node-btn {\r\n        flex: 1;\r\n        padding: 4px 8px;\r\n        font-size: 12px;\r\n        border: none;\r\n        border-radius: 3px;\r\n        color: white;\r\n        cursor: pointer;\r\n        transition: all 0.3s;\r\n\r\n        &:hover {\r\n          opacity: 0.8;\r\n        }\r\n\r\n        &:active {\r\n          transform: scale(0.95);\r\n        }\r\n\r\n        &.btn-code {\r\n          background: #67c23a;\r\n        }\r\n\r\n        &.btn-add {\r\n          background: #409eff;\r\n        }\r\n\r\n        &.btn-delete {\r\n          background: #f56c6c;\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n"],"sourceRoot":""}]);
