background: #fff;\r\n\r\n  // 操作栏\r\n  .ops-bar {\r\n    display: flex;\r\n    justify-content: space-between;\r\n    align-items: center;\r\n    padding: 10px 16px;\r\n    border-bottom: 1px solid #e8e8e8;\r\n    background: #fff;\r\n\r\n    .ops-left,\r\n    .ops-right {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 8px;\r\n    }\r\n\r\n    button {\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 6px;\r\n      padding: 6px 12px;\r\n      border: 1px solid #d9d9d9;\r\n      border-radius: 4px;\r\n      background: #fff;\r\n      color: #333;\r\n      cursor: pointer;\r\n      font-size: 13px;\r\n      transition: all 0.3s;\r\n      outline: none;\r\n\r\n      &:hover:not(:disabled) {\r\n        color: #40a9ff;\r\n        border-color: #40a9ff;\r\n      }\r\n\r\n      &:active:not(:disabled) {\r\n        background: #f5f5f5;\r\n      }\r\n\r\n      &:disabled {\r\n        opacity: 0.5;\r\n        cursor: not-allowed;\r\n      }\r\n\r\n      &.is-recording {\r\n        background: #fff2f0;\r\n        border-color: #ffccc7;\r\n        color: #ff4d4f;\r\n\r\n        &:hover:not(:disabled) {\r\n          background: #fff1f0;\r\n          border-color: #ffa39e;\r\n        }\r\n      }\r\n    }\r\n  }\r\n\r\n  // 录制进度面板\r\n  .recording-panel {\r\n    background: linear-gradient(135deg, #f5f7fa 0%, #f0f2f5 100%);\r\n    padding: 12px 16px;\r\n    border-bottom: 1px solid #e8e8e8;\r\n\r\n    .recording-header {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      align-items: center;\r\n\r\n      .recording-status {\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 8px;\r\n        font-size: 13px;\r\n        font-weight: 500;\r\n        color: #333;\r\n\r\n        .recording-dot {\r\n          width: 6px;\r\n          height: 6px;\r\n          background: #ff4d4f;\r\n          border-radius: 50%;\r\n          animation: pulse 1.5s ease-in-out infinite;\r\n        }\r\n      }\r\n\r\n      .recording-count {\r\n        font-size: 13px;\r\n        color: #666;\r\n\r\n        .count-number {\r\n          font-size: 16px;\r\n          font-weight: 600;\r\n          color: #1890ff;\r\n          margin: 0 4px;\r\n        }\r\n      }\r\n    }\r\n\r\n    .recent-methods {\r\n      margin-top: 12px;\r\n\r\n      .recent-title {\r\n        font-size: 12px;\r\n        color: #999;\r\n        margin-bottom: 8px;\r\n      }\r\n\r\n      .recent-list {\r\n        display: flex;\r\n        flex-direction: column;\r\n        gap: 6px;\r\n\r\n        .recent-item {\r\n          display: flex;\r\n          align-items: center;\r\n          gap: 8px;\r\n          padding: 6px 10px;\r\n          background: #fff;\r\n          border: 1px solid #e8e8e8;\r\n          border-radius: 4px;\r\n          font-size: 12px;\r\n          transition: all 0.2s;\r\n\r\n          &:hover {\r\n            border-color: #d9d9d9;\r\n            box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);\r\n          }\r\n\r\n          .recent-index {\r\n            display: inline-flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            min-width: 22px;\r\n            height: 18px;\r\n            background: #f5f5f5;\r\n            border-radius: 4px;\r\n            font-weight: 500;\r\n            font-size: 11px;\r\n            color: #666;\r\n          }\r\n\r\n          .recent-name {\r\n            flex: 1;\r\n            font-weight: 500;\r\n            color: #333;\r\n            overflow: hidden;\r\n            text-overflow: ellipsis;\r\n            white-space: nowrap;\r\n          }\r\n\r\n          .recent-source {\r\n            font-size: 11px;\r\n            color: #999;\r\n            max-width: 200px;\r\n            overflow: hidden;\r\n            text-overflow: ellipsis;\r\n            white-space: nowrap;\r\n          }\r\n        }\r\n      }\r\n\r\n      .interval-setting {\r\n        margin-left: auto;\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 6px;\r\n        font-size: 13px;\r\n        color: #666;\r\n        cursor: pointer;\r\n        user-select: none;\r\n      }\r\n\r\n      .interval-help {\r\n        display: inline-flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        width: 16px;\r\n        height: 16px;\r\n        font-size: 12px;\r\n        color: #999;\r\n        cursor: help;\r\n        margin-left: 2px;\r\n\r\n        &:hover {\r\n          color: #1890ff;\r\n        }\r\n      }\r\n\r\n      .interval-setting:hover {\r\n        color: #333;\r\n      }\r\n\r\n      .interval-label,\r\n      .interval-unit {\r\n        user-select: none;\r\n      }\r\n\r\n      .interval-input {\r\n        width: 110px;\r\n        height: 28px;\r\n        padding: 0 8px;\r\n        border: 1px solid #d9d9d9;\r\n        border-radius: 4px;\r\n        outline: none;\r\n        transition: all 0.3s;\r\n\r\n        &:hover:not(:disabled) {\r\n          border-color: #40a9ff;\r\n        }\r\n\r\n        &:focus:not(:disabled) {\r\n          border-color: #1890ff;\r\n          box-shadow: 0 0 0 2px rgba(24, 144, 255, 0.2);\r\n        }\r\n\r\n        &:disabled {\r\n          background: #f5f5f5;\r\n          cursor: not-allowed;\r\n        }\r\n      }\r\n    }\r\n  }\r\n\r\n  // 动画\r\n  .slide-down-enter-active,\r\n  .slide-down-leave-active {\r\n    transition: all 0.3s ease;\r\n    max-height: 300px;\r\n  }\r\n\r\n  .slide-down-enter,\r\n  .slide-down-leave-to {\r\n    max-height: 0;\r\n    opacity: 0;\r\n    overflow: hidden;\r\n  }\r\n\r\n  @keyframes pulse {\r\n    0%,\r\n    100% {\r\n      opacity: 1;\r\n      transform: scale(1);\r\n    }\r\n    50% {\r\n      opacity: 0.6;\r\n      transform: scale(1.2);\r\n    }\r\n  }\r\n\r\n  // 搜索栏\r\n  .search-bar {\r\n    position: relative;\r\n    padding: 16px;\r\n    border-bottom: 1px solid #e8e8e8;\r\n    background: #fafafa;\r\n\r\n    .search-input {\r\n      width: 100%;\r\n      height: 40px;\r\n      padding: 0 40px 0 16px;\r\n      border: 1px solid #d9d9d9;\r\n      border-radius: 4px;\r\n      font-size: 14px;\r\n      outline: none;\r\n      transition: all 0.3s;\r\n\r\n      &:hover {\r\n        border-color: #40a9ff;\r\n      }\r\n\r\n      &:focus {\r\n        border-color: #1890ff;\r\n        box-shadow: 0 0 0 2px rgba(24, 144, 255, 0.2);\r\n      }\r\n\r\n      &::placeholder {\r\n        color: #bfbfbf;\r\n      }\r\n    }\r\n\r\n    .search-icon {\r\n      position: absolute;\r\n      right: 28px;\r\n      top: 38%;\r\n      transform: translateY(-50%);\r\n      font-size: 16px;\r\n      color: #bfbfbf;\r\n      pointer-events: none;\r\n    }\r\n\r\n    .filter-checkbox {\r\n      margin-top: 8px;\r\n      display: flex;\r\n      gap: 16px;\r\n      align-items: center;\r\n      flex-wrap: wrap;\r\n\r\n      label {\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 6px;\r\n        cursor: pointer;\r\n        font-size: 13px;\r\n        color: #666;\r\n        user-select: none;\r\n\r\n        input[type='checkbox'] {\r\n          cursor: pointer;\r\n        }\r\n\r\n        &:hover {\r\n          color: #333;\r\n        }\r\n      }\r\n    }\r\n  }\r\n\r\n  // 折叠列表\r\n  .code-source-collapse {\r\n    flex: 1;\r\n    overflow-y: auto;\r\n\r\n    .collapse-title {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      align-items: center;\r\n      width: 100%;\r\n      padding: 12px;\r\n      gap: 16px;\r\n\r\n      .title-left {\r\n        flex: 1;\r\n        font-weight: 600;\r\n        font-size: 14px;\r\n        color: #333;\r\n        overflow: hidden;\r\n        text-overflow: ellipsis;\r\n        white-space: nowrap;\r\n      }\r\n\r\n      .title-right {\r\n        flex-shrink: 0;\r\n        font-size: 12px;\r\n        color: #999;\r\n        max-width: 600px;\r\n        overflow: hidden;\r\n        text-overflow: ellipsis;\r\n        white-space: nowrap;\r\n      }\r\n    }\r\n\r\n    // 加载更多\r\n    .load-more-container {\r\n      padding: 16px;\r\n      text-align: center;\r\n\r\n      .load-more-btn {\r\n        padding: 8px 24px;\r\n        border: 1px solid #d9d9d9;\r\n        border-radius: 4px;\r\n        background: #fff;\r\n        color: #666;\r\n        cursor: pointer;\r\n        font-size: 13px;\r\n        transition: all 0.3s;\r\n\r\n        &:hover {\r\n          color: #40a9ff;\r\n          border-color: #40a9ff;\r\n        }\r\n\r\n        &:active {\r\n          background: #f5f5f5;\r\n        }\r\n\r\n        &.load-all-btn {\r\n          margin-left: 12px;\r\n        }\r\n      }\r\n    }\r\n\r\n    // 加载完成提示\r\n    .load-complete {\r\n      padding: 16px;\r\n      text-align: center;\r\n      color: #999;\r\n      font-size: 12px;\r\n    }\r\n  }\r\n\r\n  // 无数据提示\r\n  .no-result {\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    flex: 1;\r\n    color: #999;\r\n    font-size: 14px;\r\n\r\n    p {\r\n      margin: 0;\r\n    }\r\n  }\r\n}\r\n"],"sourceRoot":""}]);
