import DevTool from './vueComps/DevTool.vue'
export function inPageContentRun() {
  window._techInDevPage = true // 标识在弹窗页面里面
  window._techInDevStartTime = new Date().getTime()
  setTimeout(() => {
    if (document.getElementById('tech_loading_res_inner')) {
      document.getElementById('tech_loading_res_inner').style.display = 'none' // 关闭loading
    }
  }, 200)
  // 开没两秒的定时器检测opener是否刷新过
  setInterval(() => {
    try {
      if (window.opener._iidp_dev_tool_current_starttime > window._techInDevStartTime) {
        console.log(' ==== opener 被刷新了 并 重新点了 开发 按钮 ')
        console.log(' ==== 弹窗自身关闭 ')
        window.close()
      }
      checkNodeElementHeightLight()
    } catch (e) {}
  }, 500)
  // 添加控制rem的html元素的style="font-size: 100px"
  document.documentElement.style.fontSize = '100px'
  document.body.style.fontSize = '16px'

  // 检查节点元素选中高亮状态对应的标识元素是否存在
  const checkNodeElementHeightLight = () => {
    try {
      let highlightBox = window.opener.document.getElementById('tech-devTool-highlight-box')
      if (highlightBox) {
        if (!window.opener.document.getElementById(highlightBox._tagId)) {
          highlightBox.remove()
        }
      }
      let highlightBoxGreen = window.opener.document.getElementById(
        'tech-devTool-highlight-box-green'
      )
      if (highlightBoxGreen) {
        if (!window.opener.document.getElementById(highlightBoxGreen._tagId)) {
          highlightBoxGreen.remove()
        }
      }
    } catch (e) {}
  }

  // 在body上添加一个id为devPage的div
  document.body.innerHTML += '<div id="devPage"></div>'
  new window.parent.Vue({
    render: (h) => h(DevTool)
  }).$mount('#devPage')
}
inPageContentRun()
