// 节点类型常量
const NODE_TYPES = {
  TREE: 'tree',
  GRID: 'grid',
  FORM: 'form'
}

// 节点配置
const NODE_CONFIGS = {
  // 树形结构节点
  tree_main_wrap: {
    label: '树形主容器',
    children: ['tree_main_wrap_toolbar', 'tree_main_wrap_left', 'tree_main_wrap_right']
  },
  tree_main_wrap_toolbar: { label: '树形工具栏' },
  tree_main_wrap_left: { label: '树形左侧区域' },
  tree_main_wrap_right: { label: '树形右侧区域' },

  // 表格结构节点
  main_table_search_container: { label: '主表格搜索容器' },
  container_table_search: { label: '搜索容器' },
  form_main_table_search_common: { label: '搜索表单' },
  container_table_search_wrap: { label: '搜索按钮+下拉表单容器' },
  form_main_table_search_btn: { label: '搜索按钮区域' },
  dropdown_pop_form: { label: '下拉表单容器' },
  form_main_table_search_dropdown: { label: '下拉搜索表单' },
  table_main_wrap: { label: '主表格容器' },
  table_main_toolbar: { label: '主表格工具栏' },
  table_main_table: { label: '主表格' },

  // 表单结构节点
  form_main_detail_top: { label: '详情表单主容器' },
  form_main_detail_top_header: { label: '详情页头部' },
  form_main_detail_top_items_1: { label: '详情页主表单+子表区域' },
  container_form_main_wrap: { label: '主表单容器' },
  form_main_detail_top_common: { label: '主表单' },
  container_table_main_wrap: { label: '子表容器' },
  'form-tabs-node': { label: '子表标签页容器' },

  // 树形右侧表单节点
  tree_main_wrap_right_straight: { label: '树形右侧表单容器' },
  tree_form_main_detail_top_header: { label: '树形右侧表单头部' },
  tree_table_detail: { label: '树形右侧表单容器' },
  tree_main_wrap_right_form_wrap: { label: '树形右侧表单外层容器' },
  tree_main_wrap_right_form: { label: '树形右侧表单' },
  tree_main_wrap_right_empty: { label: '暂无数据区域' }
}

/**
 * 创建节点
 */
const createNode = (id, children = [], labelText = '', idPreStr = '') => {
  const config = NODE_CONFIGS[id] || {}
  const finalLabel = labelText !== '' ? labelText : config.label || ''
  const nodeId = idPreStr + id

  return {
    id: nodeId,
    label: finalLabel ? `${finalLabel} (${nodeId})` : nodeId,
    children
  }
}

/**
 * 节点创建器 - 简化节点创建过程
 */
class NodeCreator {
  constructor(idPre = '') {
    this.idPre = idPre
  }

  node(id, children = [], labelText = '') {
    return createNode(id, children, labelText, this.idPre)
  }

  /**
   * 创建搜索相关节点
   */
  createSearchNodes(isSubTable = false) {
    const prefix = isSubTable ? '子表' : '主表'

    return this.node(
      'container_table_search',
      [
        this.node('form_main_table_search_common', [], `${prefix}搜索表单`),
        this.node(
          'container_table_search_wrap',
          [
            this.node('form_main_table_search_btn', [], `${prefix}搜索按钮区域`),
            this.node(
              'dropdown_pop_form',
              [this.node('form_main_table_search_dropdown', [], `${prefix}下拉搜索表单`)],
              `${prefix}下拉表单容器`
            )
          ],
          `${prefix}搜索表单按钮+下拉表单容器`
        )
      ],
      `${prefix}搜索容器`
    )
  }

  /**
   * 创建表格容器节点
   */
  createTableContainer(options = {}) {
    const { labelPrefix = '', hasSearch = false, hasDrawer = false, isSubTable = false } = options
    const children = []

    // 添加搜索容器（如果启用）
    if (hasSearch) {
      const searchContainer = this.node('main_table_search_container', [], `${labelPrefix}搜索容器`)
      searchContainer.children.push(this.createSearchNodes(isSubTable))
      children.push(searchContainer)
    }

    // 添加工具栏和表格
    children.push(
      this.node('table_main_toolbar', [], `${labelPrefix}表格工具栏`),
      this.node('table_main_table', [], `${labelPrefix}表格`)
    )

    // 添加抽屉容器（如果启用）
    if (hasDrawer) {
      children.push(
        this.node(
          'container_tab_pop_form_wrap',
          [
            this.node(
              'table_drawer',
              [
                this.node('table_drawer_title', [], `${labelPrefix}抽屉标题栏`),
                this.node('table_drawer_form', [], `${labelPrefix}抽屉表单`)
              ],
              `${labelPrefix}抽屉`
            )
          ],
          `${labelPrefix}抽屉容器`
        )
      )
    }

    return this.node('table_main_wrap', children, `${labelPrefix}表格容器`)
  }

  /**
   * 创建子表标签页节点
   */
  createSubTableTabs(tabs = []) {
    if (!tabs?.length) return null

    const formTabsNode = this.node('form-tabs-node', [], '子表标签页容器')

    tabs.forEach((item) => {
      const field = String(item?.body?.field || '').trim()
      if (!field) return

      const tabLabel = String(item?.label || field).trim()
      if (!tabLabel) return
      const tabCreator = new NodeCreator(this.idPre + 'tab_' + field + '_')

      const subTableContainer = tabCreator.createTableContainer({
        labelPrefix: '子表',
        hasSearch: false,
        hasDrawer: true,
        isSubTable: true
      })

      const subTableNode = tabCreator.node('table_main', [subTableContainer], `子表_${tabLabel}`)
      formTabsNode.children.push(subTableNode)
    })

    if (!formTabsNode.children.length) return null
    return formTabsNode
  }

  /**
   * 创建树形右侧表单容器节点
   */
  createTreeFormContainer() {
    return this.node(
      'tree_main_wrap_right_straight',
      [
        this.node('tree_form_main_detail_top_header', [], '树形右侧表单头部'),
        this.node(
          'tree_table_detail',
          [
            this.node(
              'tree_main_wrap_right_form_wrap',
              [this.node('tree_main_wrap_right_form', [], '树形右侧表单')],
              '树形右侧表单外层容器'
            )
          ],
          '树形右侧表单容器'
        )
      ],
      '树形右侧表单容器'
    )
  }

  /**
   * 创建基础树形结构节点
   */
  createBaseTreeStructure() {
    return this.node(
      'tree_main_wrap',
      [
        this.node('tree_main_wrap_toolbar', [], '树形工具栏'),
        this.node('tree_main_wrap_left', [], '树形左侧区域'),
        this.node(
          'tree_main_wrap_right',
          [this.node('tree_main_wrap_right_empty', [], '暂无数据区域')],
          '树形右侧区域'
        )
      ],
      '树形主容器'
    )
  }

  /**
   * 创建树形视图节点
   */
  createTreeViewNodes() {
    const treeMainWrapContainer = this.createBaseTreeStructure()
    return this.node('table_main', [treeMainWrapContainer], '主页面根节点')
  }

  /**
   * 创建表格视图节点
   */
  createGridViewNodes(hasSearch = false) {
    const tableMainWrapContainer = this.createTableContainer({
      labelPrefix: '主表',
      hasSearch,
      hasDrawer: false,
      isSubTable: false
    })

    return this.node('table_main', [tableMainWrapContainer], '主页面根节点')
  }

  /**
   * 创建表单视图节点
   */
  createFormViewNodes(tableView) {
    const formTabsNode = this.createSubTableTabs(tableView.form?.body?.tabs)

    const tableDetailWrapContainer = this.node(
      'form_main_detail_top',
      [
        this.node('form_main_detail_top_header', [], '详情页头部'),
        this.node(
          'form_main_detail_top_items_1',
          [
            this.node(
              'container_form_main_wrap',
              [this.node('form_main_detail_top_common', [], '主表单')],
              '主表单容器'
            ),
            this.node('container_table_main_wrap', formTabsNode ? [formTabsNode] : [], '子表容器')
          ],
          '详情页主表单+子表区域'
        )
      ],
      '详情表单主容器'
    )

    return this.node('table_detail', [tableDetailWrapContainer], '详情页根节点')
  }
}

/**
 * 视图类型处理器
 */
class ViewTypeHandler {
  constructor(creator, tableView) {
    this.creator = creator
    this.tableView = tableView
    this.treeData = []
  }

  /**
   * 处理左树右表格视图
   */
  handleTreeWithGridView(hasSearch) {
    const treeNode = this.creator.createTreeViewNodes()
    const gridContainer = this.creator.createTableContainer({
      labelPrefix: '主表',
      hasSearch,
      hasDrawer: false,
      isSubTable: false
    })

    const rightAreaNode = treeNode.children[0].children.find((child) =>
      child.id.includes('tree_main_wrap_right')
    )
    if (rightAreaNode) {
      rightAreaNode.children.push(gridContainer)
    }

    this.treeData.push(treeNode)
  }

  /**
   * 处理左树右表单视图
   */
  handleTreeWithFormView() {
    const treeNode = this.creator.createTreeViewNodes()

    const rightAreaNode = treeNode.children[0].children.find((child) =>
      child.id.includes('tree_main_wrap_right')
    )
    if (rightAreaNode) {
      const formContainer = this.creator.createTreeFormContainer()
      rightAreaNode.children.push(formContainer)
    }

    this.treeData.push(treeNode)
  }

  /**
   * 处理纯表格视图
   */
  handleGridView(hasSearch) {
    this.treeData.push(this.creator.createGridViewNodes(hasSearch))
  }

  /**
   * 处理纯树形视图
   */
  handleTreeView() {
    this.treeData.push(this.creator.createTreeViewNodes())
  }

  /**
   * 处理表单视图
   */
  handleFormView() {
    this.treeData.push(this.creator.createFormViewNodes(this.tableView))
  }

  getResult() {
    return this.treeData
  }
}

/**
 * 根据视图获取常用页面节点
 */
export const getCommonNodes = (vm) => {
  if (!vm) return []
  const idPre = vm.$ds?.idPre
  if (!idPre) return []

  const tableMainVm = vm.$select(idPre + 'table_main')
  const tableView = tableMainVm?.$ds?.tableView?.data?.views
  if (!tableView) return []

  const creator = new NodeCreator(idPre)
  const handler = new ViewTypeHandler(creator, tableView)

  const { tree: hasTree, grid: hasGrid, form: hasForm, search: hasSearch } = tableView

  // 处理各种视图组合
  if (hasTree && hasGrid) {
    // 左树右表格
    handler.handleTreeWithGridView(hasSearch)
  } else if (hasTree && hasForm && !hasGrid) {
    // 左树右表单
    handler.handleTreeWithFormView()
    return handler.getResult() // 提前返回，避免重复处理
  } else if (hasGrid) {
    // 纯表格视图
    handler.handleGridView(hasSearch)
  } else if (hasTree) {
    // 纯树形视图
    handler.handleTreeView()
  }

  // 处理表单视图（独立于其他视图）
  if (hasForm) {
    handler.handleFormView()
  }

  return handler.getResult()
}
