/**
 * 获取常用页面数据源配置
 */
export const getCommonDs = (vm) => {
  if (!vm) return []
  const { idPre } = vm.$ds || {}
  if (!idPre) return []

  const tableMainVm = vm.$select(`${idPre}table_main`)
  const tableView = tableMainVm?.$ds?.tableView?.data?.views
  if (!tableView) return []

  return generateDataSourceConfig(idPre, tableView)
}

/**
 * 根据视图配置生成数据源配置
 */
const generateDataSourceConfig = (idPre, tableView) => {
  const { tree: hasTree, grid: hasGrid, form: hasForm } = tableView
  const dsConfig = []

  if (hasTree) {
    handleTreeConfig(dsConfig, idPre, tableView)
    if (!hasGrid && hasForm) return dsConfig
  }
  if (hasGrid) {
    handleGridConfig(dsConfig, idPre)
  }
  if (hasForm) {
    handleFormConfig(dsConfig, idPre, tableView)
  }

  return dsConfig
}

/**
 * 处理树形结构配置
 */
const handleTreeConfig = (dsConfig, idPre, tableView) => {
  const { grid: hasGrid, form: hasForm } = tableView
  const treeNodeId = `${idPre}tree_main_wrap`

  dsConfig.push({
    nodeId: treeNodeId,
    name: 'treeData',
    remark: '获取树数据'
  })

  // 左树右表单的特殊处理
  if (!hasGrid && hasForm) {
    dsConfig.push(
      {
        nodeId: treeNodeId,
        name: 'getFormData',
        remark: '获取右侧表单数据'
      },
      {
        nodeId: treeNodeId,
        name: 'formUpdate',
        remark: '保存右侧表单数据'
      }
    )
  }
}

/**
 * 处理表格配置
 */
const handleGridConfig = (dsConfig, idPre) => {
  const tableNodeId = `${idPre}table_main`
  const tableConfigs = [
    { name: 'tableView', remark: '获取表格视图' },
    { name: 'tableData', remark: '获取表格数据' },
    { name: 'tableDataCount', remark: '查询表格数据总条数' },
    { name: 'delTableData', remark: '删除表格数据' }
  ]

  tableConfigs.forEach((config) => {
    dsConfig.push({
      nodeId: tableNodeId,
      ...config
    })
  })
}

/**
 * 处理表单配置
 */
const handleFormConfig = (dsConfig, idPre, tableView) => {
  const formNodeId = `${idPre}form_main_detail_top_common`

  // 主表单配置
  dsConfig.push(
    {
      nodeId: formNodeId,
      name: 'formSearch',
      remark: '查询表单数据'
    },
    {
      nodeId: formNodeId,
      name: 'formUpdate',
      remark: '提交表单数据'
    }
  )

  // 处理子表的表格配置
  handleTabConfigs(dsConfig, idPre, tableView)
}

/**
 * 处理子表配置
 */
const handleTabConfigs = (dsConfig, idPre, tableView) => {
  const tabs = tableView.form?.body?.tabs || []

  tabs.forEach((tab) => {
    const field = tab.body?.field
    if (!field) return

    const tabIdPre = `${idPre}tab_${field}_`
    const tabTableNodeId = `${tabIdPre}table_main`

    const tabConfigs = [
      { name: 'tableView', remark: '获取子表格视图' },
      { name: 'tableData', remark: '获取子表格数据' },
      { name: 'tableDataCount', remark: '查询子表格数据总条数' },
      { name: 'delTableData', remark: '删除子表格数据' },
      { name: 'drawerFormView', remark: '获取抽屉表单视图' },
      { name: 'drawerFormData', remark: '获取抽屉表单数据' }
    ]

    tabConfigs.forEach((config) => {
      dsConfig.push({
        nodeId: tabTableNodeId,
        ...config
      })
    })
  })
}
