export const arrayToTree = (items) => {
  try {
    if (process?.env === 'development') {
      if (hasCycle(items)) {
        return 'hasCycle'
      }
    }
  } catch (e) {}
  const result = [] // 用于存储最终的树形结构
  const map = new Map() // 使用 Map 存储所有项目,方便查找

  // 首先将所有项目存储到 map 中,便于查找
  for (const item of items) {
    map.set(item.id, { ...item, children: [] })
  }

  // 遍历每个项目,找到其父级,并将其作为子节点添加到父级的 children 数组中
  for (const item of items) {
    const { pid } = item
    if (pid === null || pid === undefined) {
      // 如果 pid 为 null 或者缺失,则表示该项目是根节点,直接添加到结果数组中
      result.push(map.get(item.id))
    } else {
      // 否则,将该项目作为子节点添加到对应父级的 children 数组中
      if (map.has(pid)) {
        const parent = map.get(pid)
        if (parent.children?.length) {
          // 按weight权重大小 插入扩展的孩子children
          let fIndex = -1
          for (let pos = 0; pos < parent.children.length; pos++) {
            if (parent.children[pos].weight < item.weight) {
              fIndex = pos
              break
            }
          }
          if (fIndex === -1) {
            parent.children.push(map.get(item.id))
          } else {
            parent.children.splice(fIndex, 0, map.get(item.id))
          }
        } else {
          parent.children.push(map.get(item.id))
        }
      }
    }
  }

  return result
}

export function extendViewTrace(id) {
  // console.log(' === this.extendView == ', this.extendView)
  let trace = []

  // 构建新对象
  let newObj = {}
  let map = window.opener.tech_app.extendView
  for (let key2 of map.keys()) {
    let getObj = map.get(key2)
    newObj[key2] = {}
    newObj[key2].content = getObj
    newObj[key2].extend = getObj?.extend
    newObj[key2].weight = getObj?.weight
    newObj[key2].ids = []
    newObj[key2]._appName = getObj._appName
    if (getObj?.selector?.pre && getObj?.selector?.attr === 'id') {
      if (getObj?.selector?.pre?.map) {
        getObj.selector.pre.map((pre) => {
          newObj[key2].ids.push(pre + getObj.selector.value)
          let curId = pre + getObj.selector.value
          if (window?.techOldIdMap?.has(curId)) {
            // 寻找旧的中文映射
            newObj[key2].ids.push(window.techOldIdMap.get(curId))
          }
        })
      }
    } else if (getObj?.selector?.attr === 'id') {
      newObj[key2].ids.push(getObj.selector.value)
      let curId = getObj.selector.value
      if (window?.techOldIdMap?.has(curId)) {
        // 寻找旧的中文映射
        newObj[key2].ids.push(window.techOldIdMap.get(curId))
      }
    }
  }

  // 按字母排序
  // let sortData = {}; // 排序后的对象
  // Object.keys(newObj).sort().map(key3 => { // .reverse()
  //   sortData[key3] = newObj[key3];
  // });

  let preSortArr = [] // 排序后的数组
  Object.keys(newObj)
    .sort()
    .map((key3) => {
      // .reverse()
      // console.log(' === newObj[key3] == ', newObj[key3]);
      // console.log(' === newObj[key3]?.extend == ', newObj[key3]?.extend);
      preSortArr.push({
        id: key3,
        label: key3,

        pid: newObj[key3]?.extend,
        weight: newObj[key3]?.weight || 0,
        value: newObj[key3]
      })
    })
  // 转树
  // console.log(' === preSortArr == ', preSortArr);
  let sortTreeData = arrayToTree(preSortArr)
  // console.log(' === sortTreeData == ', sortTreeData)
  // debugger
  if (sortTreeData === 'hasCycle') {
    throw new Error('扩展存在循环依赖，死循环')
  }
  return sortTreeData
}

export const depthFirstTraversal = (root, callback) => {
  if (!root) return

  // 先访问根节点
  callback(root)

  // 递归遍历子节点
  if (root.children) {
    for (const child of root.children) {
      depthFirstTraversal(child, callback)
    }
  }
}
