// 自定义序列化函数，处理循环引用和函数
export const serializeWithFunctions = (obj, indent = 2) => {
  const seen = new WeakSet()

  const stringify = (value, depth = 0) => {
    // 处理循环引用
    if (value !== null && typeof value === 'object') {
      if (seen.has(value)) return '"[Circular]"'
      seen.add(value)
    }

    const spaces = ' '.repeat(depth * indent)
    const nextSpaces = ' '.repeat((depth + 1) * indent)

    // 处理函数
    if (typeof value === 'function') {
      return value.toString()
    }

    // 处理 null
    if (value === null) return 'null'

    // 处理基本类型
    if (typeof value !== 'object') {
      return JSON.stringify(value)
    }

    // 处理数组
    if (Array.isArray(value)) {
      if (value.length === 0) return '[]'
      const items = value.map((item) => `${nextSpaces}${stringify(item, depth + 1)}`)
      return `[\n${items.join(',\n')}\n${spaces}]`
    }

    // 处理对象
    const keys = Object.keys(value)
    if (keys.length === 0) return '{}'

    const items = keys.map((key) => {
      const val = stringify(value[key], depth + 1)
      return `${nextSpaces}${JSON.stringify(key)}: ${val}`
    })

    return `{\n${items.join(',\n')}\n${spaces}}`
  }

  return stringify(obj)
}

/**
 * 查找目标元素，优先使用 getElementById，如果未找到或 ID 不匹配则尝试精确查询
 * @param {Window} targetWindow - 目标窗口对象
 * @param {string} elementId - 元素 ID
 * @returns {HTMLElement|null} - 找到的元素或 null
 */
export const findTargetElement = (targetWindow, elementId) => {
  if (!targetWindow || !elementId) return null

  // 获取目标元素
  let targetElement = targetWindow.document.getElementById(elementId)

  // 如果直接获取不到，或者获取到的元素ID不是精确匹配（可能是部分匹配），则尝试精确查询
  if (!targetElement || targetElement.id !== elementId) {
    const exactMatch = targetWindow.document.querySelector(`[id="${elementId}"]`)
    if (exactMatch) {
      targetElement = exactMatch
    }
  }

  return targetElement
}
