\r\n  flex-direction: column;\r\n\r\n  // 默认有动画\r\n  transition: width 0.3s ease;\r\n\r\n  // 拖拽时禁用所有动画\r\n  &.resizing {\r\n    transition: none !important;\r\n\r\n    * {\r\n      transition: none !important;\r\n    }\r\n  }\r\n\r\n  .toolbar {\r\n    padding: 5px 12px;\r\n    border-bottom: 1px solid #e4e7ed;\r\n    display: flex;\r\n    gap: 8px;\r\n    background: #fff;\r\n    align-items: center;\r\n    position: relative;\r\n    overflow: visible;\r\n    flex-shrink: 0;\r\n\r\n    .el-button {\r\n      flex-shrink: 0;\r\n      position: relative;\r\n      z-index: 0;\r\n      font-size: 0.12rem;\r\n    }\r\n\r\n    .search-container {\r\n      position: relative;\r\n      margin-left: auto;\r\n      display: flex;\r\n      align-items: center;\r\n      z-index: 10;\r\n      min-width: 36px;\r\n\r\n      .search-icon-btn {\r\n        position: relative;\r\n        z-index: 20;\r\n        padding: 0;\r\n        width: 36px;\r\n        height: 32px;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        color: #909399;\r\n\r\n        &:hover {\r\n          color: #409eff;\r\n        }\r\n      }\r\n\r\n      .search-input {\r\n        position: absolute;\r\n        right: 40px;\r\n        top: 0;\r\n        min-width: 220px;\r\n        height: 32px;\r\n        background: #fff;\r\n        border-radius: 4px;\r\n        box-shadow: 0 2px 12px rgba(0, 0, 0, 0.1);\r\n        z-index: 10;\r\n        animation: slideIn 0.3s ease-in-out;\r\n\r\n        ::v-deep .el-input__inner {\r\n          height: 32px;\r\n          line-height: 32px;\r\n          padding-left: 30px;\r\n        }\r\n\r\n        ::v-deep .el-input__icon {\r\n          line-height: 32px;\r\n        }\r\n      }\r\n\r\n      @keyframes slideIn {\r\n        from {\r\n          opacity: 0;\r\n          transform: translateX(20px);\r\n        }\r\n        to {\r\n          opacity: 1;\r\n          transform: translateX(0);\r\n        }\r\n      }\r\n    }\r\n  }\r\n\r\n  ::v-deep .toolbar .el-checkbox__label {\r\n    font-size: 0.12rem;\r\n    line-height: 32px;\r\n    margin-left: 4px;\r\n  }\r\n\r\n  .tree-header {\r\n    padding: 5px 8px;\r\n    border-bottom: 1px solid #e4e7ed;\r\n    background: #fff;\r\n    flex-shrink: 0;\r\n  }\r\n\r\n  .tree-content {\r\n    width: 100%;\r\n    flex: 1;\r\n    overflow-y: auto;\r\n    padding: 8px;\r\n    transition: all 0.3s ease;\r\n    position: relative;\r\n    // 添加 will-change 提示浏览器优化\r\n    will-change: width;\r\n    // 确保内容不会被宽度变化影响布局\r\n    min-width: 0;\r\n\r\n    &::-webkit-scrollbar {\r\n      width: 6px;\r\n    }\r\n\r\n    &::-webkit-scrollbar-thumb {\r\n      background: #b8bbc2;\r\n      border-radius: 3px;\r\n\r\n      &:hover {\r\n        background: #8d9096;\r\n      }\r\n    }\r\n\r\n    .no-result {\r\n      display: flex;\r\n      flex-direction: column;\r\n      align-items: center;\r\n      justify-content: center;\r\n      height: 200px;\r\n      color: #909399;\r\n\r\n      i {\r\n        font-size: 36px;\r\n        margin-bottom: 16px;\r\n        opacity: 0.5;\r\n      }\r\n\r\n      p {\r\n        font-size: 14px;\r\n        margin: 0;\r\n      }\r\n    }\r\n\r\n    ::v-deep .el-tree-node__expand-icon {\r\n      display: none;\r\n    }\r\n\r\n    ::v-deep .el-tree-node__content {\r\n      height: 32px;\r\n      border-radius: 4px;\r\n      transition: background 0.3s;\r\n\r\n      &:hover {\r\n        background: #f5f7fa;\r\n      }\r\n    }\r\n\r\n    ::v-deep .el-tree-node.is-current > .el-tree-node__content {\r\n      background: #ecf5ff;\r\n      color: #409eff;\r\n    }\r\n\r\n    ::v-deep .el-tree-node.is-highlighted > .el-tree-node__content {\r\n      background-color: #ecf5ff !important;\r\n      color: #409eff;\r\n      animation: pulse 1s infinite alternate;\r\n    }\r\n\r\n    @keyframes pulse {\r\n      from {\r\n        box-shadow: 0 0 0 0 rgba(64, 158, 255, 0.4);\r\n      }\r\n      to {\r\n        box-shadow: 0 0 0 6px rgba(64, 158, 255, 0);\r\n      }\r\n    }\r\n\r\n    .custom-tree-node {\r\n      flex: 1;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: space-between;\r\n      font-size: 14px;\r\n      padding-right: 8px;\r\n      overflow: hidden;\r\n\r\n      .node-left {\r\n        display: flex;\r\n        align-items: center;\r\n        flex: 1;\r\n        overflow: hidden;\r\n        min-width: 0;\r\n      }\r\n\r\n      .node-right {\r\n        display: flex;\r\n        align-items: center;\r\n        width: auto;\r\n        min-width: 28px;\r\n        justify-content: flex-end;\r\n      }\r\n\r\n      .node-icon {\r\n        width: 12px;\r\n        height: 12px;\r\n        border-radius: 50%;\r\n        margin-right: 8px;\r\n        flex-shrink: 0;\r\n      }\r\n\r\n      .node-label {\r\n        flex: 1;\r\n        overflow: hidden;\r\n        text-overflow: ellipsis;\r\n        white-space: nowrap;\r\n        height: 36px;\r\n        line-height: 36px;\r\n        padding-left: 6px;\r\n      }\r\n\r\n      .node-expand {\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        width: 20px;\r\n        height: 20px;\r\n        cursor: pointer;\r\n        color: #909399;\r\n        transition: all 0.3s;\r\n        border-radius: 4px;\r\n        flex-shrink: 0;\r\n        margin-left: 8px;\r\n\r\n        &:hover {\r\n          color: #409eff;\r\n          background: #ecf5ff;\r\n        }\r\n\r\n        i {\r\n          font-size: 12px;\r\n        }\r\n      }\r\n\r\n      .node-expand-placeholder {\r\n        width: 20px;\r\n        height: 20px;\r\n        flex-shrink: 0;\r\n        margin-left: 8px;\r\n      }\r\n\r\n      &:hover .node-actions {\r\n        display: flex;\r\n      }\r\n      &.range-selected {\r\n        background: #ecf5ff;\r\n        border-radius: 4px;\r\n      }\r\n    }\r\n  }\r\n\r\n  &.no-select {\r\n    .tree-content {\r\n      user-select: none;\r\n      -webkit-user-select: none;\r\n      -moz-user-select: none;\r\n      -ms-user-select: none;\r\n    }\r\n    .tree-content ::selection {\r\n      background: transparent;\r\n      color: inherit;\r\n    }\r\n  }\r\n\r\n  &.collapsed {\r\n    width: 16px;\r\n    min-width: 16px;\r\n    overflow: hidden;\r\n    border-right: none;\r\n    background-color: #f5f7fa;\r\n\r\n    .tree-content {\r\n      overflow: hidden;\r\n      opacity: 0;\r\n      padding: 0;\r\n    }\r\n\r\n    .tree-header {\r\n      display: none;\r\n    }\r\n\r\n    .toolbar {\r\n      display: none;\r\n    }\r\n\r\n    .panel-toggle {\r\n      left: 0;\r\n      border-left: 1px solid #e4e7ed;\r\n      border-radius: 4px;\r\n    }\r\n  }\r\n\r\n  .resize-handle {\r\n    position: absolute;\r\n    right: -4px;\r\n    top: 0;\r\n    bottom: 0;\r\n    width: 8px;\r\n    cursor: col-resize;\r\n    z-index: 100;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n\r\n    &:hover .resize-handle-line {\r\n      background: #409eff;\r\n      opacity: 1;\r\n    }\r\n\r\n    &:active .resize-handle-line {\r\n      background: #66b1ff;\r\n    }\r\n\r\n    .resize-handle-line {\r\n      width: 2px;\r\n      height: 40px;\r\n      background: #dcdfe6;\r\n      border-radius: 1px;\r\n      opacity: 0;\r\n    }\r\n  }\r\n\r\n  .panel-toggle {\r\n    position: absolute;\r\n    right: -1px;\r\n    top: 50%;\r\n    transform: translateY(-50%);\r\n    width: 16px;\r\n    height: 40px;\r\n    background: #f5f7fa;\r\n    border: 1px solid #e4e7ed;\r\n    border-right: none;\r\n    border-radius: 4px 0 0 4px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    cursor: pointer;\r\n    transition: all 0.2s;\r\n    z-index: 100;\r\n    flex-shrink: 0;\r\n\r\n    &:hover {\r\n      background: #e9ecef;\r\n      width: 18px;\r\n    }\r\n\r\n    i {\r\n      font-size: 12px;\r\n      color: #606266;\r\n      transition: color 0.2s;\r\n    }\r\n\r\n    &:hover i {\r\n      color: #409eff;\r\n    }\r\n  }\r\n}\r\n"],"sourceRoot":""}]);
