ite-space: nowrap;\r\n      }\r\n    }\r\n  }\r\n\r\n  .detail-panel {\r\n    flex: 1;\r\n    display: flex;\r\n    flex-direction: column;\r\n    overflow: hidden;\r\n    background: #fff;\r\n\r\n    // 新增顶部操作栏样式\r\n    .detail-header {\r\n      padding: 8px 10px;\r\n      border-bottom: 1px solid #e4e7ed;\r\n      background: #fff;\r\n      display: flex;\r\n      justify-content: flex-end;\r\n      align-items: center;\r\n\r\n      .el-button {\r\n        font-size: 13px;\r\n      }\r\n    }\r\n\r\n    .detail-tabs {\r\n      flex: 1;\r\n      height: 100%;\r\n      display: flex;\r\n      flex-direction: column;\r\n\r\n      ::v-deep .el-tabs__header {\r\n        margin: 0;\r\n        background: #fff;\r\n        border-bottom: 1px solid #e4e7ed;\r\n      }\r\n\r\n      ::v-deep .el-tabs__nav-wrap {\r\n        padding: 0 16px;\r\n      }\r\n\r\n      ::v-deep .el-tabs__item {\r\n        height: 44px;\r\n        line-height: 44px;\r\n        font-size: 14px;\r\n        transition: color 0.3s;\r\n\r\n        &:hover {\r\n          color: #409eff;\r\n        }\r\n\r\n        &.is-active {\r\n          color: #409eff;\r\n        }\r\n      }\r\n\r\n      ::v-deep .el-tabs__active-bar {\r\n        height: 2px;\r\n        background: #409eff;\r\n        transition: transform 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);\r\n      }\r\n\r\n      &:not(.tabs-ready) {\r\n        ::v-deep .el-tabs__active-bar {\r\n          opacity: 0;\r\n        }\r\n      }\r\n\r\n      ::v-deep .el-tabs__content {\r\n        flex: 1;\r\n        overflow-y: auto;\r\n        padding: 0;\r\n\r\n        &::-webkit-scrollbar {\r\n          width: 6px;\r\n        }\r\n\r\n        &::-webkit-scrollbar-thumb {\r\n          background: #b8bbc2;\r\n          border-radius: 3px;\r\n          transition: background 0.2s;\r\n\r\n          &:hover {\r\n            background: #8d9096;\r\n          }\r\n        }\r\n      }\r\n\r\n      ::v-deep .el-tab-pane {\r\n        height: 100%;\r\n      }\r\n\r\n      .tab-label {\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 6px;\r\n\r\n        .question-icon {\r\n          font-size: 14px;\r\n          color: #909399;\r\n          cursor: pointer;\r\n          transition: color 0.3s;\r\n\r\n          &:hover {\r\n            color: #409eff;\r\n          }\r\n        }\r\n      }\r\n\r\n      .detail-content {\r\n        padding: 20px;\r\n        height: 100%;\r\n        overflow-y: auto;\r\n\r\n        &::-webkit-scrollbar {\r\n          width: 6px;\r\n        }\r\n\r\n        &::-webkit-scrollbar-thumb {\r\n          background: #b8bbc2;\r\n          border-radius: 3px;\r\n          transition: background 0.2s;\r\n\r\n          &:hover {\r\n            background: #8d9096;\r\n          }\r\n        }\r\n\r\n        &::-webkit-scrollbar-track {\r\n          background: #f5f7fa;\r\n        }\r\n      }\r\n    }\r\n  }\r\n\r\n  .bottom-editor-panel {\r\n    border-top: 1px solid #e4e7ed;\r\n    background: #fff;\r\n    display: flex;\r\n    flex-direction: column;\r\n    position: relative;\r\n    min-height: 100px;\r\n    max-height: 600px;\r\n    transition: height 0.1s ease-out;\r\n\r\n    .resize-handle {\r\n      position: absolute;\r\n      top: -4px;\r\n      left: 0;\r\n      right: 0;\r\n      height: 8px;\r\n      cursor: ns-resize;\r\n      z-index: 10;\r\n      transition: background 0.2s;\r\n\r\n      &:hover,\r\n      &.resizing {\r\n        background: rgba(64, 158, 255, 0.1);\r\n      }\r\n\r\n      &::after {\r\n        content: '';\r\n        position: absolute;\r\n        top: 3px;\r\n        left: 50%;\r\n        transform: translateX(-50%);\r\n        width: 40px;\r\n        height: 2px;\r\n        background: #dcdfe6;\r\n        border-radius: 1px;\r\n        transition: background 0.2s;\r\n      }\r\n\r\n      &:hover::after,\r\n      &.resizing::after {\r\n        background: #409eff;\r\n      }\r\n    }\r\n\r\n    .editor-content {\r\n      flex: 1;\r\n      overflow: hidden;\r\n      padding: 5px;\r\n    }\r\n\r\n    .info-text {\r\n      padding: 7px 2px;\r\n      font-size: 13px;\r\n      color: #303133;\r\n\r\n      .el-icon-info {\r\n        margin-right: 5px;\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n// 上传弹窗样式\r\n.upload-area {\r\n  border: 2px dashed #dcdfe6;\r\n  border-radius: 6px;\r\n  padding: 40px 20px;\r\n  text-align: center;\r\n  transition: all 0.3s;\r\n  cursor: pointer;\r\n\r\n  &.is-dragover {\r\n    border-color: #409eff;\r\n    background: #ecf5ff;\r\n  }\r\n\r\n  .el-icon-upload {\r\n    font-size: 67px;\r\n    color: #c0c4cc;\r\n    margin-bottom: 16px;\r\n  }\r\n\r\n  .upload-text {\r\n    margin-bottom: 20px;\r\n\r\n    p {\r\n      margin: 8px 0;\r\n      color: #606266;\r\n      font-size: 14px;\r\n    }\r\n\r\n    .upload-hint {\r\n      font-size: 12px;\r\n      color: #909399;\r\n    }\r\n  }\r\n}\r\n\r\n.file-list {\r\n  margin-top: 20px;\r\n  max-height: 300px;\r\n  overflow-y: auto;\r\n\r\n  .file-item {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    padding: 10px;\r\n    border: 1px solid #e4e7ed;\r\n    border-radius: 4px;\r\n    margin-bottom: 8px;\r\n    transition: all 0.3s;\r\n\r\n    &:hover {\r\n      background: #f5f7fa;\r\n    }\r\n\r\n    .file-name {\r\n      flex: 1;\r\n      font-size: 14px;\r\n      color: #303133;\r\n      overflow: hidden;\r\n      text-overflow: ellipsis;\r\n      white-space: nowrap;\r\n    }\r\n\r\n    .file-status {\r\n      margin: 0 10px;\r\n      font-size: 12px;\r\n      padding: 2px 8px;\r\n      border-radius: 3px;\r\n\r\n      &.pending {\r\n        color: #909399;\r\n        background: #f4f4f5;\r\n      }\r\n\r\n      &.uploading {\r\n        color: #409eff;\r\n        background: #ecf5ff;\r\n      }\r\n\r\n      &.success {\r\n        color: #67c23a;\r\n        background: #f0f9ff;\r\n      }\r\n\r\n      &.error {\r\n        color: #f56c6c;\r\n        background: #fef0f0;\r\n      }\r\n    }\r\n\r\n    .el-icon-close {\r\n      cursor: pointer;\r\n      color: #909399;\r\n      font-size: 16px;\r\n      transition: color 0.3s;\r\n\r\n      &:hover {\r\n        color: #f56c6c;\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n::v-deep .el-dialog {\r\n  border-radius: 8px;\r\n}\r\n\r\n::v-deep .el-dialog__header {\r\n  padding: 16px 20px;\r\n  border-bottom: 1px solid #e4e7ed;\r\n\r\n  .el-dialog__title {\r\n    font-weight: 600;\r\n    font-size: 16px;\r\n    color: #303133;\r\n  }\r\n}\r\n\r\n::v-deep .el-dialog__body {\r\n  padding: 20px;\r\n}\r\n\r\n.dialog-content {\r\n  padding: 10px 0;\r\n  line-height: 1.6;\r\n  color: #606266;\r\n  font-size: 14px;\r\n}\r\n\r\n::v-deep .el-empty {\r\n  padding: 60px 0;\r\n}\r\n\r\n.effect-table-container {\r\n  margin-top: 20px;\r\n\r\n  .extend-ids-cell {\r\n    display: flex;\r\n    flex-direction: column;\r\n    align-items: flex-start;\r\n    min-height: 32px;\r\n    max-height: 200px;\r\n    overflow-y: auto;\r\n\r\n    &::-webkit-scrollbar {\r\n      width: 4px;\r\n    }\r\n\r\n    &::-webkit-scrollbar-thumb {\r\n      background: #dcdfe6;\r\n      border-radius: 2px;\r\n    }\r\n\r\n    .no-data {\r\n      color: #909399;\r\n      font-size: 12px;\r\n    }\r\n\r\n    ::v-deep .el-checkbox {\r\n      margin-right: 0;\r\n\r\n      .el-checkbox__label {\r\n        font-size: 12px;\r\n        padding-left: 6px;\r\n      }\r\n    }\r\n  }\r\n\r\n  ::v-deep .el-textarea__inner {\r\n    font-family: 'Consolas', 'Monaco', monospace;\r\n    font-size: 12px;\r\n  }\r\n}\r\n"],"sourceRoot":""}]);
