import { getFetch } from './request'

/**
 * 文件搜索器类
 * 用于在文件树中递归搜索内容
 */
export class FileSearcher {
  /**
   * @param {Object} options 配置项
   * @param {Function} options.onMatchFound 找到匹配项时的回调 (node, matches) => void
   * @param {Function} options.onSearchComplete 搜索完成时的回调 () => void
   * @param {Function} options.onError 发生错误时的回调 (error) => void
   */
  constructor(options = {}) {
    this.onMatchFound = options.onMatchFound || (() => {})
    this.onSearchComplete = options.onSearchComplete || (() => {})
    this.onError = options.onError || (() => {})
    this.isSearching = false
    this.abortController = null
  }

  /**
   * 开始搜索
   * @param {Array} fileTree 文件树数据
   * @param {String} keyword 搜索关键词
   */
  async search(fileTree, keyword) {
    if (!keyword || !keyword.trim()) return

    // 如果正在搜索，先取消上一次搜索
    if (this.isSearching) {
      this.cancel()
    }

    this.isSearching = true
    this.abortController = new AbortController()

    try {
      await this.traverseTree(fileTree, keyword)
    } catch (error) {
      if (error.name === 'AbortError') {
        console.log('搜索已取消')
      } else {
        console.error('搜索出错:', error)
        this.onError(error)
      }
    } finally {
      this.isSearching = false
      this.abortController = null
      this.onSearchComplete()
    }
  }

  /**
   * 取消搜索
   */
  cancel() {
    if (this.abortController) {
      this.abortController.abort()
    }
    this.isSearching = false
  }

  /**
   * 递归遍历文件树
   * @param {Array} nodes 节点数组
   * @param {String} keyword 关键词
   */
  async traverseTree(nodes, keyword) {
    if (!nodes || !nodes.length) return

    for (const node of nodes) {
      if (this.abortController && this.abortController.signal.aborted) {
        throw new DOMException('Aborted', 'AbortError')
      }

      // 如果节点有子节点，递归遍历（即使它是文件类型，也可能包含子节点）
      if (node.children && node.children.length) {
        await this.traverseTree(node.children, keyword)
      }

      // 只要是文件类型，就进行搜索（即使它有子节点）
      if (node.type === 'file') {
        await this.searchInFile(node, keyword)
      }
    }
  }

  /**
   * 在单个文件中搜索
   * @param {Object} node 文件节点
   * @param {String} keyword 关键词
   */
  async searchInFile(node, keyword) {
    try {
      // 获取文件内容
      // 注意：这里假设 getFetch 可以被 abort，但实际 fetch 需要传递 signal
      // 由于 getFetch 封装可能未暴露 signal，这里仅做逻辑控制
      const res = await getFetch('/api/fs/file', { path: node.path })

      // 注意：某些后端接口返回结构可能不同，需要做兼容
      // 有时直接返回文件内容字符串，有时在 content 字段中
      const content = typeof res === 'string' ? res : res?.data?.content || res?.content || ''

      if (content && content.includes(keyword)) {
        // 简单的包含匹配，如果需要更复杂的匹配（如正则、行号），可以在这里扩展
        this.onMatchFound(node, { keyword })
      }
    } catch (error) {
      // 忽略文件读取错误，继续搜索下一个
      console.warn(`读取文件失败: ${node.path}`, error)
    }
  }
}
